def reindex (f : State ≃ State') : Buchi State Symbol ≃ Buchi State' Symbol where
  toFun nba := {
    Tr s x t := nba.Tr (f.symm s) x (f.symm t)
    start := f '' nba.start
    accept := f.symm ⁻¹' nba.accept
  }
  invFun nba' := {
    Tr s x t := nba'.Tr (f s) x (f t)
    start := f.symm '' nba'.start
    accept := f ⁻¹' nba'.accept

